-- تحديث أسئلة كيمياء 3 التي عُدّلت بعد الرفع (11 سؤالًا في 7 هدفًا). مولّد آليًا بـ scripts/build-chem3-patch.js — لا تعدّله يدويًا.
-- لا يغيّر حالة الاعتماد. آمن للتكرار. إن لم تكن نفّذت ملفات seed-chem3 بعد فلا حاجة إليه (ملفات seed محدّثة).
begin;
update public.questions set stem = 'اعتمادًا على الجدول 2-1 (بعض الأحماض الشائعة وقواعدها المرافقة)، أيّ المواد الآتية يظهر فيه حمضًا في صف وقاعدةً مرافقة في صف آخر، فيُعد مادة مترددة؟', updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K3-C2-L1-O13') and type = 'mcq' and number = 7);
update public.questions set stem = 'ماذا تدل عليه القيمة الأصغر لثابت تأين الحمض Ka عند مقارنة حمضين ضعيفين بالتركيز نفسه وعند درجة الحرارة نفسها؟', updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K3-C2-L2-O02') and type = 'mcq' and number = 1);
update public.questions set options = '["5.0 × 10⁻⁶ M، والمحلول حمضي","2.0 × 10⁵ M، والمحلول قاعدي","5.0 × 10⁻⁶ M، والمحلول قاعدي","2.0 × 10⁻²³ M، والمحلول حمضي"]'::jsonb, updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K3-C2-L3-O03') and type = 'mcq' and number = 4);
update public.question_answers set distractor_notes = '["قيمة [OH⁻] صحيحة، لكن [OH⁻] > [H⁺] يعني أن المحلول قاعدي لا حمضي.","قسم [H⁺] على Kw بدلًا من قسمة Kw على [H⁺]، فنتج 2.0 × 10⁵ M وهو ناتج غير ممكن.","","ضرب Kw في [H⁺] بدلًا من القسمة، ثم حكم بالحمضية لصغر الناتج."]'::jsonb where question_id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K3-C2-L3-O03') and type = 'mcq' and number = 4);
update public.questions set stem = 'أيّ الأوساط الآتية يجب أن تكون قيمة pH فيه حمضية بدرجة كبيرة (بين 1.6 و1.8)؟', options = '["دم الإنسان","العصارة المعدية","ماء حوض قناديل البحر","الماء النقي عند 298 K"]'::jsonb, thinking_level = 'فهم', question_kind = 'تمييز', difficulty = 'سهل', source_ref = 'الكتاب ص 88 — المحاليل المنظمة في الكائنات الحية (الشكل 2-27)', updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K3-C2-L4-O08') and type = 'mcq' and number = 6);
update public.question_answers set explanation = 'يذكر الكتاب أن قيمة pH للعصارة المعدية يجب أن تبقى بين 1.6 و1.8 فهي شديدة الحمضية، أما الدم فبين 7.1 و7.7 وحوض قناديل البحر بين 8.1 و8.4، والماء النقي pH له 7.', distractor_notes = '["pH الدم بين 7.1 و7.7، أي قريب من التعادل لا شديد الحمضية.","","pH حوض قناديل البحر بين 8.1 و8.4، أي قاعدي ضعيف.","pH الماء النقي عند 298 K يساوي 7، أي متعادل."]'::jsonb where question_id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K3-C2-L4-O08') and type = 'mcq' and number = 6);
update public.questions set stem = 'عند دخول كمية قليلة من حمض إلى مجرى الدم تبقى قيمة pH ضمن المدى 7.1–7.7 بوجود نظام H₂CO₃/HCO₃⁻. ما التفسير الصحيح؟', options = '["تتفاعل أيونات H⁺ المضافة مع H₂CO₃ فتزداد أيونات HCO₃⁻ في الدم","ينزاح الاتزان إلى اليمين فتزداد أيونات H⁺ زيادة كبيرة","تتحول جميع أيونات HCO₃⁻ إلى أيونات OH⁻ في الحال","تتفاعل أيونات H⁺ المضافة مع HCO₃⁻ فينزاح الاتزان إلى اليسار ويُستهلك معظمها"]'::jsonb, thinking_level = 'تحليل', question_kind = 'تفسير', source_ref = 'الكتاب ص 90 — مختبر حل المشكلات: كيف يحافظ الدم على قيمة pH', updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K3-C2-L4-O08') and type = 'mcq' and number = 7);
update public.question_answers set explanation = 'تتفاعل أيونات H⁺ المضافة مع أيونات HCO₃⁻ مكوّنة H₂CO₃، فينزاح الاتزان إلى اليسار بحسب مبدأ لوتشاتلييه ويُستهلك معظم H⁺ المضاف، فلا يتغير pH الدم كثيرًا.', distractor_notes = '["H⁺ المضافة تتفاعل مع القاعدة HCO₃⁻ لا مع الحمض H₂CO₃، وعدد HCO₃⁻ يقل لا يزداد.","زيادة H⁺ تدفع الاتزان إلى اليسار لا اليمين، ولو زاد H⁺ كثيرًا لتغير pH.","HCO₃⁻ لا يتحول كليًا إلى OH⁻؛ بل يستهلك جزءًا منه فقط في التفاعل مع H⁺.",""]'::jsonb where question_id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K3-C2-L4-O08') and type = 'mcq' and number = 7);
update public.questions set stem = 'يذكر الكتاب المدى المطلوب لقيمة pH في ثلاثة أوساط: الدم (7.1–7.7)، والعصارة المعدية (1.6–1.8)، ومياه أحواض قناديل البحر (8.1–8.4). رتّب هذه الأوساط تصاعديًا بحسب قيمة pH وحدّد طبيعة كل منها (حمضي، أو قريب من التعادل، أو قاعدي ضعيف)، ثم فسّر لماذا تحتاج هذه الأوساط إلى المحافظة على pH ضمن مدى ضيق.', question_kind = 'مقارنة وتفسير', difficulty = 'متوسط', source_ref = 'الكتاب ص 88 — المحاليل المنظمة في الكائنات الحية (الشكل 2-27)', updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K3-C2-L4-O08') and type = 'essay' and number = 3);
update public.question_answers set model_answer = 'الترتيب التصاعدي: العصارة المعدية (1.6–1.8) ثم دم الإنسان (7.1–7.7) ثم مياه أحواض قناديل البحر (8.1–8.4). العصارة المعدية وسط حمضي بدرجة كبيرة، والدم قريب من التعادل إلى قاعدي ضعيف، ومياه الحوض قاعدية ضعيفة. وتحتاج إلى مدى ضيق لأن تغير pH خارجه يضر الكائن: في الدم تفقد البروتينات تراكيبها ومقدرتها على أداء عملها، وفي المعدة يُضعف الهضم، ولا تعيش قناديل البحر في غير مدى pH المناسب لها؛ ويحافظ على ذلك وجود محاليل منظمة تقاوم تغير pH.', answer_elements = '["الترتيب التصاعدي الصحيح","طبيعة كل وسط","سبب الحاجة إلى مدى ضيق في كل وسط","دور المحاليل المنظمة"]'::jsonb, marks = '[{"element":"الترتيب الصحيح","marks":1},{"element":"طبيعة الأوساط الثلاثة","marks":1},{"element":"سبب الحاجة إلى مدى ضيق","marks":1},{"element":"دور المحاليل المنظمة","marks":1}]'::jsonb, rubric = '[{"level":"4 درجات","description":"ترتيب صحيح وطبيعة كل وسط وتفسير صحيح مع ذكر دور المحاليل المنظمة"},{"level":"3 درجات","description":"ثلاثة من العناصر الأربعة"},{"level":"2 درجتان","description":"الترتيب والطبيعة فقط"},{"level":"1 درجة","description":"ترتيب صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, common_errors = '["عكس الترتيب بين الدم وحوض قناديل البحر","وصف الدم بأنه حمضي","القول إن المحلول المنظم يثبت pH مهما أضيف إليه"]'::jsonb where question_id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K3-C2-L4-O08') and type = 'essay' and number = 3);
update public.questions set stem = 'استُعمل الميثيل البرتقالي (مدى تغير لونه من pH 3.2 إلى 4.4) في معايرة حمض ضعيف بقاعدة قوية تقع نقطة تكافؤها عند pH ≈ 8.2. ماذا تتوقع؟', updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K3-C2-L4-O11') and type = 'mcq' and number = 5);
update public.questions set stem = 'تُستعمل أقطاب الخارصين والنحاس نفسها في خلية جلفانية تعمل تلقائيًا، ثم تُوصل الأقطاب بمصدر جهد خارجي أكبر من جهد الخلية وبقطبية معاكسة لتعمل خلية تحليل كهربائي. ما اتجاه تدفق الإلكترونات في الدائرة الخارجية في كل حالة؟', updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K3-C4-L3-O03') and type = 'mcq' and number = 4);
update public.questions set stem = 'التحليل الكهربائي للماء تفاعل غير تلقائي. ما الذي يجعل خلية التحليل قادرة على إنتاج الهيدروجين والأكسجين من الماء؟', options = '["تزويد الخلية بمصدر طاقة كهربائية خارجي يدفع التفاعل في الاتجاه غير التلقائي","ارتفاع درجة حرارة الماء وحدها حتى يتحلل إلى عناصره","تحول الماء إلى هيدروجين وأكسجين تلقائيًا عند تماسه بالقطبين","وجود غاز الأكسجين في الخلية الذي يعكس اتجاه التفاعل"]'::jsonb, thinking_level = 'فهم', question_kind = 'تفسير', updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K3-C4-L3-O07') and type = 'mcq' and number = 4);
update public.question_answers set explanation = 'التفاعل غير تلقائي، فلا يحدث إلا بتزويد الخلية بطاقة كهربائية من مصدر خارجي تجبر التفاعل على السير في الاتجاه المعاكس لاتجاه تفاعل خلية الوقود التلقائي.', distractor_notes = '["","الحرارة وحدها لا تحلل الماء في ظروف خلية التحليل؛ فالمطلوب طاقة كهربائية.","لو كان تلقائيًا لما احتاج إلى مصدر طاقة، والتفاعل هنا غير تلقائي.","الأكسجين أحد ناتجي التفاعل، وليس عاملًا يعكس اتجاهه."]'::jsonb where question_id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K3-C4-L3-O07') and type = 'mcq' and number = 4);
update public.questions set stem = 'في خلية الوقود الهيدروجينية التي يمثل تفاعلها عكس التحليل الكهربائي للماء، أيّ المادتين تتأكسد وأيّهما تُختزل؟', options = '["يُختزل الهيدروجين ويتأكسد الأكسجين","يتأكسد الهيدروجين ويُختزل الأكسجين","يتأكسد كلٌّ من الهيدروجين والأكسجين","يُختزل كلٌّ من الهيدروجين والأكسجين"]'::jsonb, question_kind = 'تحديد المؤكسد والمختزل', updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K3-C4-L3-O07') and type = 'mcq' and number = 5);
update public.question_answers set explanation = 'في التفاعل 2H₂ + O₂ → 2H₂O يرتفع عدد تأكسد الهيدروجين من 0 إلى +1 فيتأكسد، وينخفض عدد تأكسد الأكسجين من 0 إلى −2 فيُختزل.', distractor_notes = '["عدد تأكسد الهيدروجين يزداد من 0 إلى +1، فهو يتأكسد لا يُختزل.","","لا بد أن تحدث الأكسدة والاختزال معًا؛ فالأكسجين ينقص عدد تأكسده فيُختزل.","لا بد أن تحدث الأكسدة والاختزال معًا؛ فالهيدروجين يزداد عدد تأكسده فيتأكسد."]'::jsonb where question_id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K3-C4-L3-O07') and type = 'mcq' and number = 5);
update public.questions set stem = 'يُنتج الهيدروجين بالتحليل الكهربائي للماء، ويُستعمل وقودًا في خلية الوقود التي تعيد تكوين الماء. فسّر لماذا لا يُعدّ ربط العمليتين معًا مصدرًا لطاقة كهربائية مجانية، مستندًا إلى اتجاه كل تفاعل وتلقائيته، ثم بيّن أهمية التحليل الكهربائي للماء.', thinking_level = 'تحليل', question_kind = 'تفسير وربط', updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K3-C4-L3-O07') and type = 'essay' and number = 2);
update public.question_answers set model_answer = 'التحليل الكهربائي للماء 2H₂O → 2H₂ + O₂ تفاعل غير تلقائي يحتاج إلى طاقة كهربائية من مصدر خارجي، أما تفاعل خلية الوقود 2H₂ + O₂ → 2H₂O فهو عكسه وتفاعل تلقائي ينتج طاقة كهربائية. لذلك فإن الطاقة المستهلكة في التحليل لا تقل عن الطاقة الناتجة من خلية الوقود، فلا نحصل على طاقة مجانية. وأهمية التحليل الكهربائي للماء أنه إحدى طرائق إنتاج الهيدروجين الذي يُستعمل لأغراض تجارية ووقودًا.', answer_elements = '["التحليل غير تلقائي ويحتاج طاقة خارجية","تفاعل خلية الوقود هو العكس وتلقائي وينتج طاقة","الطاقة المستهلكة لا تقل عن الناتجة فلا طاقة مجانية","أهمية التحليل: إنتاج الهيدروجين"]'::jsonb, solution_steps = '[]'::jsonb, marks = '[{"element":"اتجاه كل تفاعل وتلقائيته","marks":1.5},{"element":"تفسير عدم وجود طاقة مجانية","marks":1.5},{"element":"أهمية التحليل الكهربائي للماء","marks":1}]'::jsonb, rubric = '[{"level":"4 درجات","description":"يبيّن اتجاه التفاعلين وتلقائيتهما ويفسر عدم وجود طاقة مجانية ويذكر الأهمية"},{"level":"3 درجات","description":"يبيّن الاتجاه والتلقائية ويفسر دون ذكر الأهمية، أو العكس"},{"level":"2 درجتان","description":"يبيّن اتجاه التفاعلين فقط"},{"level":"1 درجة","description":"يذكر الأهمية فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, common_errors = '["الخلط بين التفاعل التلقائي وغير التلقائي في الخليتين","الاعتقاد بأن خلية الوقود تنتج طاقة أكبر مما يستهلكه التحليل","عدّ التحليل الكهربائي للماء تفاعلًا يحدث تلقائيًا"]'::jsonb where question_id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K3-C4-L3-O07') and type = 'essay' and number = 2);
commit;
